-- Seven complete EL097/EL099E final reading passages, all 51 original
-- questions and their original options from the user's NUMO academic bank.
-- Q2.6 explicitly lacks passage evidence for a unique answer and remains
-- in the inactive question bank for review. 50 graded objective questions.
WITH passages_data AS(
 SELECT value AS row FROM jsonb_array_elements($numo_read_json$[{"n":"01","title":"My Family","body":"My name is Ahmad, and I have a wonderful family. There are four people in my family: my mom,\nmy dad, my sister, and me. We love spending time together. My mom is kind. She cooks delicious\nmeals. My dad is funny and tells jokes that make us laugh. My sister is smart and helps me with my\nhomework. We enjoy going on family trips and making happy memories.","source":"F1 p.2 |","questions":[{"id":"1.1","position":101,"prompt":"How many people are there in Ahmad's family?","options":[{"label":"a","text":"Two"},{"label":"b","text":"Three"},{"label":"c","text":"Four"},{"label":"d","text":"Six"}],"key":"c","answer":"Four","note":"","type":"MULTIPLE_CHOICE"},{"id":"1.2","position":102,"prompt":"What does Ahmad's mom do?","options":[{"label":"a","text":"She tells jokes"},{"label":"b","text":"She cooks delicious meals"},{"label":"c","text":"She helps with homework"},{"label":"d","text":"She goes on family trips"}],"key":"b","answer":"She cooks delicious meals","note":"","type":"MULTIPLE_CHOICE"},{"id":"1.3","position":103,"prompt":"How does he describe his dad?","options":[{"label":"a","text":"Kind and caring"},{"label":"b","text":"Serious and strict"},{"label":"c","text":"Smart and helpful"},{"label":"d","text":"Funny and joke-teller"}],"key":"d","answer":"Funny and joke-teller","note":"","type":"MULTIPLE_CHOICE"},{"id":"1.4","position":104,"prompt":"Who helps Ahmad with his homework?","options":[{"label":"a","text":"Sister"},{"label":"b","text":"Dad"},{"label":"c","text":"Mom"},{"label":"d","text":"Both mom and dad"}],"key":"a","answer":"Sister","note":"","type":"MULTIPLE_CHOICE"},{"id":"1.5","position":105,"prompt":"What does Ahmed enjoy doing with his family?","options":[{"label":"a","text":"Going to the movies"},{"label":"b","text":"Playing video games"},{"label":"c","text":"Going on family trips"}],"key":"c","answer":"Going on family trips","note":"","type":"MULTIPLE_CHOICE"}]},{"n":"02","title":"Dear Omar — English Course","body":"Dear Omar I hope this email finds you well. I wanted to share some exciting news with you. I am\ncurrently attending an English course in England. The weather in England is rainy and it's better to\nhave your umbrella with you when you go out. The course is called \"English for Beginners” and it\nis being taught by Ms. Johnson. The course is two months long and it costs £1000. The schedule is\nMonday to Friday and the curriculum covers grammar, vocabulary, speaking, listening, reading,\nand writing. I am enjoying the course and I feel like it is helping me improve my English skills. I\nthink you would benefit from taking a similar course. It would be great if we could attend a course\ntogether sometime. Best regards, Shadi","source":"F1 p.2–3 |","questions":[{"id":"2.1","position":201,"prompt":"What is the purpose of the email?","options":[{"label":"a","text":"To invite a friend to a party"},{"label":"b","text":"To ask the friend for a favor"},{"label":"c","text":"To check up on the friend"},{"label":"d","text":"To inform the friend about an English course"}],"key":"d","answer":"To inform the friend about an English course","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.2","position":202,"prompt":"Where is the English course located?","options":[{"label":"a","text":"In Japan"},{"label":"b","text":"In England"},{"label":"c","text":"In Saudi Arabia"},{"label":"d","text":"In the United States"}],"key":"b","answer":"In England","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.3","position":203,"prompt":"How long is the English course?","options":[{"label":"a","text":"One week"},{"label":"b","text":"Two weeks"},{"label":"c","text":"One month"},{"label":"d","text":"Two months"}],"key":"d","answer":"Two months","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.4","position":204,"prompt":"What is the name of the English course?","options":[{"label":"a","text":"English for Beginners"},{"label":"b","text":"English for Advanced Learners"},{"label":"c","text":"English for Business"},{"label":"d","text":"English for Tourists"}],"key":"a","answer":"English for Beginners","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.5","position":205,"prompt":"What is the name of the teacher?","options":[{"label":"a","text":"Mr. Smith"},{"label":"b","text":"Ms. Johnson"},{"label":"c","text":"Mr. Brown"},{"label":"d","text":"Ms. Davis"}],"key":"b","answer":"Ms. Johnson","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.6","position":206,"prompt":"What is the teacher's teaching style?","options":[{"label":"a","text":"Strict"},{"label":"b","text":"Laid-back"},{"label":"c","text":"Interactive"},{"label":"d","text":"Boring"}],"key":null,"answer":null,"note":"The email names Ms. Johnson, but does not describe her teaching style. No option is supported by the","type":"MULTIPLE_CHOICE"},{"id":"2.7","position":207,"prompt":"What is the course fee?","options":[{"label":"a","text":"£100"},{"label":"b","text":"£500"},{"label":"c","text":"£1000"},{"label":"d","text":"£5000"}],"key":"c","answer":"£1000","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.8","position":208,"prompt":"What is the course schedule?","options":[{"label":"a","text":"Monday to Friday"},{"label":"b","text":"Saturday and Sunday"},{"label":"c","text":"Monday, Wednesday, and Friday"},{"label":"d","text":"Tuesday and Thursday"}],"key":"a","answer":"Monday to Friday","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.9","position":209,"prompt":"The course curriculum includes ......................","options":[{"label":"a","text":"Only grammar and Vocabulary"},{"label":"b","text":"Only listening and speaking"},{"label":"c","text":"Only reading and Writing"},{"label":"d","text":"The four skills, vocabulary and grammar"}],"key":"d","answer":"The four skills, vocabulary and grammar","note":"","type":"MULTIPLE_CHOICE"},{"id":"2.10","position":210,"prompt":"What is the course level?","options":[{"label":"a","text":"Beginner"},{"label":"b","text":"Intermediate"},{"label":"c","text":"Advanced"},{"label":"d","text":"All levels"}],"key":"a","answer":"Beginner","note":"","type":"MULTIPLE_CHOICE"}]},{"n":"03","title":"The Cloud","body":"A cloud is made of water drops floating in the sky. The sky can be full of water. But most of the\ntime you can't see the water. The drops of water are too small to see. (They) have turned into a gas\ncalled water vapor. There are many kinds of clouds. Clouds get their names in many ways. One\nway is by where they are found in the sky. Some clouds are high up in the sky. Low clouds form\ncloser to Earth's surface. These clouds are called fog. Middle clouds are found between low and\nhigh clouds. Most of the water in clouds is in very small droplets. The droplets are so light that they\nfloat in the air. Sometimes those droplets join with other droplets. Then they turn into larger drops.\nWhen that happens, gravity causes them to fall to Earth. We call the falling water drops \"rain.\"\nWhen the air is colder, the water may form snowflakes instead.","source":"F1 p.4–5 |","questions":[{"id":"3.1","position":301,"prompt":"A cloud is made of water ......... floating in the sky.","options":[{"label":"a","text":"vapors"},{"label":"b","text":"fogs"},{"label":"c","text":"gases"},{"label":"d","text":"drops"}],"key":"d","answer":"drops","note":"","type":"MULTIPLE_CHOICE"},{"id":"3.2","position":302,"prompt":"What are the types of clouds?","options":[{"label":"a","text":"High, low and middle."},{"label":"b","text":"High and low"},{"label":"c","text":"High and middle."},{"label":"d","text":"Low and middle"}],"key":"a","answer":"High, low and middle.","note":"","type":"MULTIPLE_CHOICE"},{"id":"3.3","position":303,"prompt":"Which word means (stay on the surface and not sink)?","options":[{"label":"a","text":"Droplets"},{"label":"b","text":"Vapor"},{"label":"c","text":"Float"},{"label":"d","text":"Rain"}],"key":"c","answer":"Float","note":"","type":"MULTIPLE_CHOICE"},{"id":"3.4","position":304,"prompt":"Drops of water turn into a gas called water ................","options":[{"label":"a","text":"Cloud"},{"label":"b","text":"Snow"},{"label":"c","text":"Rain"},{"label":"d","text":"Vapor"}],"key":"d","answer":"Vapor","note":"","type":"MULTIPLE_CHOICE"},{"id":"3.5","position":305,"prompt":"When droplets join with other droplets in hot air, they cause ............","options":[{"label":"a","text":"Fog"},{"label":"b","text":"Snow"},{"label":"c","text":"Rain"},{"label":"d","text":"Vapor"}],"key":"c","answer":"Rain","note":"'Rain' is supported when droplets join. The question's phrase 'in hot air' is not given in the passage.","type":"MULTIPLE_CHOICE"},{"id":"3.6","position":306,"prompt":"The pronoun (They) in sentence 6 refers back to?","options":[{"label":"a","text":"Clouds"},{"label":"b","text":"Drops"},{"label":"c","text":"Water"},{"label":"d","text":"Fog"}],"key":"b","answer":"Drops","note":"","type":"MULTIPLE_CHOICE"},{"id":"3.7","position":307,"prompt":"When the air is colder, the water may form .......... instead of rain.","options":[{"label":"a","text":"Fog"},{"label":"b","text":"Snow"},{"label":"c","text":"Snowflakes"},{"label":"d","text":"Vapor"}],"key":"c","answer":"Snowflakes","note":"","type":"MULTIPLE_CHOICE"},{"id":"3.8","position":308,"prompt":"The drops of water in the sky are too small to see.","options":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"key":"a","answer":"True","note":"","type":"TRUE_FALSE"},{"id":"3.9","position":309,"prompt":"There are not many kinds of clouds.","options":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"key":"b","answer":"False","note":"","type":"TRUE_FALSE"},{"id":"3.10","position":310,"prompt":"Low clouds form closer to Earth's surface.","options":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"key":"a","answer":"True","note":"","type":"TRUE_FALSE"}]},{"n":"04","title":"Hilltown","body":"Hi Friends! My name's Sandra and I live in Hilltown. It is in the south of England. It isn't a very big\ntown About 9,000 people live here. There are about thirty shops in Hilltown and there are three\nsupermarkets You can buy everything in the town what you need. There are two banks and a post\noffice in Main Street There is a police station and a library, too. You can find a big market where\nyou can buy fresh fruit. vegetables, meat and dairy products. I like going to the market with my\nmum. There are three churches in the town centre and there is a park, too. In the park children\ncan play because there is a playground. In our town you can find some restaurants and there are\nfive cafés. My favourite café is Lescave. It's in Park Street and the ice cream is fantastic here! There\nare three elementary and two high schools in Hilltown. My school is in Mill Street. We have got a\nvery nice building. Next to our school there is a sports centre/Every Wednesday afternoon we play\nbadminton. If you want to see a film you can go to the cinema in our town, but unfortunately there\naren't any theatres here. I like living in Hilltown because it is a calm, neat place and/people are\nfriendly","source":"F4 p.12–13 | F2 (repeated) · F4 (repeated)","questions":[{"id":"4.1","position":401,"prompt":"Where can you find Hilltown?","options":[{"label":"a","text":"It is in the east of England."},{"label":"b","text":"It is in the north of England."},{"label":"c","text":"It is in the west of England."},{"label":"d","text":"It is in the south of England."}],"key":"d","answer":"It is in the south of England.","note":"","type":"MULTIPLE_CHOICE"},{"id":"4.2","position":402,"prompt":"How many people live in the town?","options":[{"label":"a","text":"Nine hundred"},{"label":"b","text":"Nine thousand"},{"label":"c","text":"Night million"},{"label":"d","text":"Nighty thousand."}],"key":"b","answer":"Nine thousand","note":"","type":"MULTIPLE_CHOICE"},{"id":"4.3","position":403,"prompt":"People have to go to another town if they want to do the shopping.","options":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"key":"b","answer":"False","note":"","type":"TRUE_FALSE"},{"id":"4.4","position":404,"prompt":"Where's Sandra's school?","options":[{"label":"a","text":"It is in Mill Street."},{"label":"b","text":"It is in the Main Street."},{"label":"c","text":"It is in Park Street."},{"label":"d","text":"It is in the Market Street."}],"key":"a","answer":"It is in Mill Street.","note":"","type":"MULTIPLE_CHOICE"},{"id":"4.5","position":405,"prompt":"What does the pronoun (it) in paragraph one refer to?","options":[{"label":"a","text":"Sandra"},{"label":"b","text":"Hilltown"},{"label":"c","text":"school"},{"label":"d","text":"shop"}],"key":"b","answer":"Hilltown","note":"","type":"MULTIPLE_CHOICE"}]},{"n":"05","title":"Dubai","body":"Dubai is a big city in the United Arab Emirates (UAE). A long time ago, it was just a small village\nwhere people fished. But now, it's a place with lots of tall buildings and exciting things. Imagine a\nbuilding that's super, super high. It's called the Burj Khalifa, and it's the tallest building in the\nwhole world! You can go up there and see the whole city from way up high. In Dubai, you can find\nboth old and new things. There's a special area called the Al Fahidi Historical Neighborhood. It has\nnarrow streets and old houses made of special materials. But there are also fancy hotels and big\nshopping centers. Dubai has lots of fancy hotels. 'They' are like big, beautiful houses by the sea.\nSome of them even have their private beaches! Have you ever been to a really big mall? Well,\nDubai Mall is like a whole city inside a building! There are fancy stores, an ice rink, and even an\naquarium. And sometimes, they have a big shopping festival with discounts and fireworks. Around\nDubai, there's a huge desert. People can ride in special cars and go up and down the sandy hills.\nWhen the sun goes down, they have fun at a desert camp. So, Dubai is a mix of old and new, with\ntall buildings, fancy hotels, and lots of things to explore!","source":"F4 p.10–11 | F2 (repeated) · F4 (repeated)","questions":[{"id":"5.1","position":501,"prompt":"What is the best title for the passage?","options":[{"label":"a","text":"The Desert around the City"},{"label":"b","text":"The Burj Khalifa"},{"label":"c","text":"Dubai Mall"},{"label":"d","text":"Everything about Dubai City"}],"key":"d","answer":"Everything about Dubai City","note":"","type":"MULTIPLE_CHOICE"},{"id":"5.2","position":502,"prompt":"What was Dubai like in the past?","options":[{"label":"a","text":"A big city with tall buildings"},{"label":"b","text":"A small fishing village"},{"label":"c","text":"A desert with dunes"},{"label":"d","text":"A modern shopping paradise"}],"key":"b","answer":"A small fishing village","note":"","type":"MULTIPLE_CHOICE"},{"id":"5.3","position":503,"prompt":"What is the tallest building in the world?","options":[{"label":"a","text":"The Burj Khalifa"},{"label":"b","text":"The Dubai Mall"},{"label":"c","text":"The Atlantis, the Palm Resort"},{"label":"d","text":"The Al Fahidi Historical Neighborhood"}],"key":"a","answer":"The Burj Khalifa","note":"","type":"MULTIPLE_CHOICE"},{"id":"5.4","position":504,"prompt":"Which part of Dubai takes visitors back in time with narrow alleys and old houses?","options":[{"label":"a","text":"The Dubai Mall"},{"label":"b","text":"The Al Fahidi Historical Neighborhood"},{"label":"c","text":"The Palm Jumeirah"},{"label":"d","text":"The Burj Khalifa"}],"key":"b","answer":"The Al Fahidi Historical Neighborhood","note":"","type":"MULTIPLE_CHOICE"},{"id":"5.5","position":505,"prompt":"What does the pronoun 'They' refer to?","options":[{"label":"a","text":"The Burj Khalifa"},{"label":"b","text":"The Al Fahidi Historical Neighborhood"},{"label":"c","text":"The hotels"},{"label":"d","text":"The Dubai Mall"}],"key":"c","answer":"The hotels","note":"","type":"MULTIPLE_CHOICE"},{"id":"5.6","position":506,"prompt":"Dubai's desert surrounds the city.","options":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"key":"a","answer":"True","note":"","type":"TRUE_FALSE"},{"id":"5.7","position":507,"prompt":"Visitors can go ….......... after the sun goes down.","options":[{"label":"a","text":"walking"},{"label":"b","text":"swimming"},{"label":"c","text":"camping"},{"label":"d","text":"fishing"}],"key":"c","answer":"camping","note":"","type":"MULTIPLE_CHOICE"},{"id":"5.8","position":508,"prompt":"Dubai is a mix of old and ……............","options":[{"label":"a","text":"fast"},{"label":"b","text":"small"},{"label":"c","text":"slow"},{"label":"d","text":"new"}],"key":"d","answer":"new","note":"","type":"MULTIPLE_CHOICE"}]},{"n":"06","title":"My Job is Special!","body":"For most people, a job means they get up at 7:00 am and drive to work by 8:30 or 9:00 am. Later,\nthey have lunch at noon, and then they start work again at 1:00 pm. Finally, they finish work at\nabout 5:00 pm and then go home and have dinner with their family. That kind of job is okay for\nmost people, but my job is special and I love it! I’m a commercial airline pilot. That means I don’t\ndrive to work, I fly! In fact, I fly to many different destinations in the world and I have friends in\nmany countries. Usually, I fly between countries in Asia, North America and South America. It’s not\nsurprising, then, that my best friend lives in Japan and we stay in touch by Facebook and e-mail –\nwhen I’m in Tokyo, he always invites me to have dinner with him and his family. In fact, my\nfavorite food is sushi. Another good friend of mine – Gustavo – lives in Brasilia. That’s the capital\ncity of Brazil. Gustavo and I love to watch football games together when I visit. Is my job perfect?\nNo, it’s not. Because I fly across many different time zones, I sometimes go to bed at 2:00 am. At\nother times, I go to bed at 2:00 pm. That kind of schedule isn’t easy. In addition, my job often\nseparates me from my wife and two children. They live in New York and often I am many\nthousands of miles away. Sometimes I miss them very much. However, I think I have an exciting\njob.","source":"F3 p.1–2 |","questions":[{"id":"6.1","position":601,"prompt":"What is the main idea of the article?","options":[{"label":"a","text":"The man has friends in many countries."},{"label":"b","text":"He can say, ‘Hello’ in many languages."},{"label":"c","text":"His job is different from most people's jobs."}],"key":"c","answer":"His job is different from most people's jobs.","note":"","type":"MULTIPLE_CHOICE"},{"id":"6.2","position":602,"prompt":"The man likes his job.","options":[{"label":"a","text":"TRUE"},{"label":"b","text":"FALSE"},{"label":"c","text":"He doesn't say."}],"key":"a","answer":"TRUE","note":"","type":"MULTIPLE_CHOICE"},{"id":"6.3","position":603,"prompt":"Where does his best friend live?","options":[{"label":"a","text":"New York"},{"label":"b","text":"Tokyo"},{"label":"c","text":"Brasilia"}],"key":"b","answer":"Tokyo","note":"","type":"MULTIPLE_CHOICE"},{"id":"6.4","position":604,"prompt":"How many countries does he fly to?","options":[{"label":"a","text":"eighteen"},{"label":"b","text":"three"},{"label":"c","text":"He doesn't say."}],"key":"c","answer":"He doesn't say.","note":"","type":"MULTIPLE_CHOICE"},{"id":"6.5","position":605,"prompt":"Where does he say likes to watch football games?","options":[{"label":"a","text":"in North America"},{"label":"b","text":"in Tokyo"},{"label":"c","text":"in Brazil"}],"key":"c","answer":"in Brazil","note":"","type":"MULTIPLE_CHOICE"},{"id":"6.6","position":606,"prompt":"He always goes to sleep at the same time every day.","options":[{"label":"a","text":"TRUE"},{"label":"b","text":"FALSE"},{"label":"c","text":"He doesn't say."}],"key":"b","answer":"FALSE","note":"","type":"MULTIPLE_CHOICE"},{"id":"6.7","position":607,"prompt":"What does the word 'them' refer to?","options":[{"label":"a","text":"football games"},{"label":"b","text":"his family"},{"label":"c","text":"his friends"}],"key":"b","answer":"his family","note":"","type":"MULTIPLE_CHOICE"},{"id":"6.8","position":608,"prompt":"What does he say about his job?","options":[{"label":"a","text":"It's perfect."},{"label":"b","text":"He must learn many languages."},{"label":"c","text":"It has some problems but he likes it."}],"key":"c","answer":"It has some problems but he likes it.","note":"","type":"MULTIPLE_CHOICE"}]},{"n":"07","title":"London","body":"London is one of the largest cities in the world. It is the capital of England.London has been\ngrowing very quickly since the beginning of the 19th century. It now has a population of more than\nsix millions spread over large area of suburbs called Greater London. London as we know it today\nis really a series of cities and towns, which all joined together as it's population grew over the\nyears. The people who live in London come from many different religions and cultures. There are\nmany communities, from Asia, Afr west India. This makes London has many of the problems of all\nlarge cities. It suffers from too much traffic, it also suffers from pollution and noise problem. Many\nof London buildings are old, built in the last century but many are new. Public transport is also a\nmixture of old and new underground railway was built seventy or eighty years ago, although new\nlines were built in 1960s and 1970s.","source":"F3 p.3–4 |","questions":[{"id":"7.1","position":701,"prompt":"The people who live in London come from..............","options":[{"label":"a","text":"Many different religions"},{"label":"b","text":"Many different cultures"},{"label":"c","text":"Different religions and cultures"},{"label":"d","text":"America only"}],"key":"c","answer":"Different religions and cultures","note":"","type":"MULTIPLE_CHOICE"},{"id":"7.2","position":702,"prompt":"What does London suffer from?","options":[{"label":"a","text":"Too much traffic"},{"label":"b","text":"Air pollution"},{"label":"c","text":"Noise pollution"},{"label":"d","text":"All the above"}],"key":"d","answer":"All the above","note":"","type":"MULTIPLE_CHOICE"},{"id":"7.3","position":703,"prompt":"Public transport in London is........","options":[{"label":"a","text":"Old"},{"label":"b","text":"New"},{"label":"c","text":"A mixture of old and new"},{"label":"d","text":"Rather new"}],"key":"c","answer":"A mixture of old and new","note":"","type":"MULTIPLE_CHOICE"},{"id":"7.4","position":704,"prompt":"What does the underlined word \"series\" mean?","options":[{"label":"a","text":"Many buildings"},{"label":"b","text":"A number of similar things"},{"label":"c","text":"Different things"},{"label":"d","text":"Cities"}],"key":"b","answer":"A number of similar things","note":"","type":"MULTIPLE_CHOICE"},{"id":"7.5","position":705,"prompt":"What is the capital of England?","options":[{"label":"a","text":"London"},{"label":"b","text":"Cardiff"},{"label":"c","text":"U.K"},{"label":"d","text":"Paris"}],"key":"a","answer":"London","note":"","type":"MULTIPLE_CHOICE"}]}]$numo_read_json$::jsonb)
), inserted_passages AS(
 INSERT INTO public.intensive_passages(id,course_id,title,body)
 SELECT md5('NUMO:EL097:FINAL:PASSAGE:'||(row->>'n'))::uuid,
 (SELECT id FROM public.intensive_courses WHERE code='EL097_EL099E'),row->>'title',row->>'body'
 FROM passages_data ON CONFLICT(id) DO NOTHING RETURNING id
), reading_data AS(
 SELECT p.row->>'n' AS passage_n,p.row->>'title' AS passage_title,
 p.row->>'source' AS passage_source,q.value AS row
 FROM passages_data p CROSS JOIN LATERAL jsonb_array_elements(p.row->'questions') AS q(value)
), inserted_questions AS(
 INSERT INTO public.intensive_questions
 (id,course_id,exam_category,skill,type,difficulty,prompt,passage_id,
 grading_mode,correct_boolean,marks,reference_source,reference_unit,reference_page,
 reference_evidence,tags,is_active)
 SELECT md5('NUMO:EL097:FINAL:READING:'||(row->>'id'))::uuid,
 (SELECT id FROM public.intensive_courses WHERE code='EL097_EL099E'),
 'FINAL','Reading',row->>'type','MEDIUM',row->>'prompt',
 md5('NUMO:EL097:FINAL:PASSAGE:'||passage_n)::uuid,
 'AUTO', CASE WHEN row->>'type'='TRUE_FALSE' THEN (row->>'key')='a' ELSE NULL END,
 1,'NUMO EL097 Final Answered Question Bank · 4 source collections',
 'Reading · '||passage_title,
 COALESCE(substring(passage_source FROM 'p\\.([0-9]+)'),'source reading passage'),
 CASE WHEN coalesce(row->>'note','')<>'' THEN 'EL097_FINAL_SOURCE_NOTE: '||(row->>'note') ELSE NULL END,
 ARRAY['EL097-FINAL','PASSAGE='||passage_n,'SOURCE_Q='||(row->>'id'),'SOURCE='||passage_source],
 (row->>'key') IS NOT NULL
 FROM reading_data
 ON CONFLICT(id) DO NOTHING RETURNING id
), choices_added AS(
 INSERT INTO public.intensive_question_options(id,question_id,label,value,is_correct,position)
 SELECT md5('NUMO:EL097:FINAL:READING:'||(d.row->>'id')||':OPTION:'||(o.value->>'label'))::uuid,
 q.id,o.value->>'label',o.value->>'text',
 COALESCE((o.value->>'label')=(d.row->>'key'),false),
 ascii(o.value->>'label')-96
 FROM reading_data d JOIN inserted_questions q ON q.id=md5('NUMO:EL097:FINAL:READING:'||(d.row->>'id'))::uuid
 CROSS JOIN LATERAL jsonb_array_elements(d.row->'options') AS o(value)
 ON CONFLICT(id) DO NOTHING RETURNING id
), linked AS(
 INSERT INTO public.intensive_exam_questions(exam_id,section_id,question_id,marks,position)
 SELECT 'cf9c621b-1611-fcb7-3f63-58542eb59774'::uuid,
 'a8da6beb-988f-a789-8905-0490f8d2dc0e'::uuid,q.id,1, (d.row->>'position')::integer
 FROM reading_data d JOIN inserted_questions q ON q.id=md5('NUMO:EL097:FINAL:READING:'||(d.row->>'id'))::uuid
 WHERE (d.row->>'key') IS NOT NULL ON CONFLICT DO NOTHING RETURNING id
)
SELECT (SELECT COUNT(*) FROM inserted_passages) passages_imported,
(SELECT COUNT(*) FROM inserted_questions) reading_questions_imported,
(SELECT COUNT(*) FROM choices_added) original_choices_imported,
(SELECT COUNT(*) FROM linked) graded_questions_linked;